import importlib.metadata


def load_classes_implemented_by_plugins(classes_group, logger=None):
    """
    Load classes from given classes-group implemented by installed plugins.

    It reads implemented-classes-specification defined by plugin.
    That specification has a form of setuptools entry point like::

    setup(
    ...
    entry_points={'<classes_group>':[
    '<Class1Name> = <Class1_implementation>',
    '<Class2Name> = <Class2_implementation>', ...],
    ...}
    )

    `<Class_implementation>` shows where class is implemented inside plugin; uses format `<package_name>:<ClassName>`

    Please note that single plugin may declare "I'm implementing multiple classes" or even
    "I'm implementing multiple classes in multiple classes_groups".

    Example::

    setup(
    ...
    entry_points={'UE_POOLS':[
    'AndroidUePool=ta_ue_plugin_android.ue.android.androiduepool:AndroidUePool',
    'SoundcardAndroidUePool=ta_ue_plugin_android.ue.android.soundcard.soundcardandroiduepool:SoundcardAndroidUePool']}
    )

    :param classes_group: group of classes to search for (like: UE_POOLS, MBMS_GW_POOLS, UE_TYPES, ...)
    :param logger: where to put logs
    :return: mapping class-name to class-implementation for given classes_group
    """
    known_implementations = {}
    entry_points = importlib.metadata.entry_points()
    entry_points = remove_entry_points(entry_points)

    group_entry_points = entry_points.get(classes_group, [])
    for entry_point in group_entry_points:
        if logger:
            logger.debug(f'Plugin entry point: {entry_point}')
        class_name = entry_point.name
        try:
            class_implementation = entry_point.load()
            known_implementations[class_name] = class_implementation
        # we intentionally catch all exceptions
        # since we don't want incorrect plugin to break whole abstract lib core
        except Exception as err:  # pylint: disable=broad-except
            class_display_name = f"{entry_point}"
            if logger:
                logger.warning(f"Failed {class_display_name} class creation, error: {err!r}")
    return known_implementations


def remove_entry_points(entry_points_obj):
    """
    Removes specific entry points from the provided entry points structure, supporting both legacy (dict-based)
    and modern (EntryPoints object) formats depending on Python version.

    This function filters out entry points whose `value` attribute contains any of the substrings listed
    in the internal `removal_list`. It supports both:
    - Python < 3.10: where entry points are grouped in a dictionary with group names as keys
    - Python ≥ 3.10/3.12: where entry points are returned as an EntryPoints object

    :param entry_points_obj: Either a dictionary of entry points (group → list of EntryPoint objects),
                             or an EntryPoints object (as returned by importlib.metadata.entry_points()).
    :type entry_points_obj: dict[str, list[EntryPoint]] | importlib.metadata.EntryPoints
    :return: A dictionary mapping group names to filtered lists of EntryPoint objects.
    :rtype: dict[str, list[EntryPoint]]
    """

    # According to jira ticket UTETAF-7511, we need to remove the Viavi plugin from the list of plugins
    removal_list = ["taf.ue.plugin.viavi"]
    cleaned_entry_points = {}

    if isinstance(entry_points_obj, dict):
        groups = entry_points_obj.items()
    else:
        unique_groups = {ep.group for ep in entry_points_obj}
        groups = ((group, entry_points_obj.select(group=group)) for group in unique_groups)

    for group, entry_points in groups:
        cleaned_entry_points[group] = [
            ep for ep in entry_points if not any(removal in ep.value for removal in removal_list)
        ]

    return cleaned_entry_points
